sql.where:
DEL_FLAG = '0'

    AND ENTERPRISE_ID = #{queryVo.enterpriseId}


    AND ENTERPRISE_NAME LIKE CONCAT('%', #{queryVo.enterpriseName}, '%')


    AND STATEMENT_TYPE = #{queryVo.statementType}


    AND STATEMENT_NAME LIKE CONCAT('%', #{queryVo.statementName}, '%')


    AND REPORTING_PERIOD = #{queryVo.reportingPeriod}


    AND REPORTING_YEAR = #{queryVo.reportingYear}


    AND REPORTING_MONTH = #{queryVo.reportingMonth}




            AND COMPILATION_STATUS IN ('待开始', 'not_started', 'NOT_STARTED')


            AND COMPILATION_STATUS IN ('进行中', 'in_progress', 'IN_PROGRESS')


            AND COMPILATION_STATUS IN ('已完成', 'completed', 'COMPLETED')


            AND COMPILATION_STATUS IN ('已暂停', 'paused', 'PAUSED')


            AND COMPILATION_STATUS IN ('已取消', 'cancelled', 'CANCELLED')


            AND COMPILATION_STATUS = #{queryVo.compilationStatus}




    AND COMPILATION_PROGRESS >= #{queryVo.compilationProgressMin}


    AND COMPILATION_PROGRESS <= #{queryVo.compilationProgressMax}


    AND PLANNED_START_TIME >= #{queryVo.plannedStartTimeBegin}


    AND PLANNED_START_TIME <= #{queryVo.plannedStartTimeEnd}


    AND PLANNED_END_TIME >= #{queryVo.plannedEndTimeBegin}


    AND PLANNED_END_TIME <= #{queryVo.plannedEndTimeEnd}


    AND COMPILATION_MANAGER LIKE CONCAT('%', #{queryVo.compilationManager}, '%')


    AND COMPILATION_DEPARTMENT LIKE CONCAT('%', #{queryVo.compilationDepartment}, '%')


    AND DATA_COLLECTION_STATUS = #{queryVo.dataCollectionStatus}


    AND DATA_COLLECTION_PROGRESS >= #{queryVo.dataCollectionProgressMin}


    AND DATA_COLLECTION_PROGRESS <= #{queryVo.dataCollectionProgressMax}


    AND DATA_QUALITY_SCORE >= #{queryVo.dataQualityScoreMin}


    AND DATA_QUALITY_SCORE <= #{queryVo.dataQualityScoreMax}




            AND AUDIT_STATUS IN ('未提交', 'not_submitted', 'NOT_SUBMITTED')


            AND AUDIT_STATUS IN ('待审核', 'pending_audit', 'PENDING_AUDIT', 'pending')


            AND AUDIT_STATUS IN ('初审通过', 'first_audit_passed', 'FIRST_AUDIT_PASSED')


            AND AUDIT_STATUS IN ('复审通过', 'second_audit_passed', 'SECOND_AUDIT_PASSED')


            AND AUDIT_STATUS IN ('终审通过', 'final_audit_passed', 'FINAL_AUDIT_PASSED')


            AND AUDIT_STATUS IN ('已签字确认', 'signed_confirmed', 'SIGNED_CONFIRMED')


            AND AUDIT_STATUS = #{queryVo.auditStatus}




    AND AUDIT_PROGRESS >= #{queryVo.auditProgressMin}


    AND AUDIT_PROGRESS <= #{queryVo.auditProgressMax}


    AND FIRST_AUDITOR LIKE CONCAT('%', #{queryVo.firstAuditor}, '%')


    AND FIRST_AUDIT_TIME >= #{queryVo.firstAuditTimeBegin}


    AND FIRST_AUDIT_TIME <= #{queryVo.firstAuditTimeEnd}


    AND SECOND_AUDITOR LIKE CONCAT('%', #{queryVo.secondAuditor}, '%')


    AND SECOND_AUDIT_TIME >= #{queryVo.secondAuditTimeBegin}


    AND SECOND_AUDIT_TIME <= #{queryVo.secondAuditTimeEnd}


    AND FINAL_AUDITOR LIKE CONCAT('%', #{queryVo.finalAuditor}, '%')


    AND FINAL_AUDIT_TIME >= #{queryVo.finalAuditTimeBegin}


    AND FINAL_AUDIT_TIME <= #{queryVo.finalAuditTimeEnd}


    AND SIGNATORY LIKE CONCAT('%', #{queryVo.signatory}, '%')


    AND SIGNATURE_TIME >= #{queryVo.signatureTimeBegin}


    AND SIGNATURE_TIME <= #{queryVo.signatureTimeEnd}


    AND QUALITY_CONTROL_STATUS = #{queryVo.qualityControlStatus}


    AND QUALITY_ASSESSMENT_RESULT = #{queryVo.qualityAssessmentResult}


    AND ACCURACY_SCORE >= #{queryVo.accuracyScoreMin}


    AND ACCURACY_SCORE <= #{queryVo.accuracyScoreMax}


    AND COMPLETENESS_SCORE >= #{queryVo.completenessScoreMin}


    AND COMPLETENESS_SCORE <= #{queryVo.completenessScoreMax}


    AND TIMELINESS_SCORE >= #{queryVo.timelinessScoreMin}


    AND TIMELINESS_SCORE <= #{queryVo.timelinessScoreMax}


    AND COMPLIANCE_SCORE >= #{queryVo.complianceScoreMin}


    AND COMPLIANCE_SCORE <= #{queryVo.complianceScoreMax}


    AND OVERALL_QUALITY_SCORE >= #{queryVo.overallQualityScoreMin}


    AND OVERALL_QUALITY_SCORE <= #{queryVo.overallQualityScoreMax}


    AND ISSUE_COUNT >= #{queryVo.issueCountMin}


    AND ISSUE_COUNT <= #{queryVo.issueCountMax}


    AND CRITICAL_ISSUE_COUNT >= #{queryVo.criticalIssueCountMin}


    AND CRITICAL_ISSUE_COUNT <= #{queryVo.criticalIssueCountMax}


    AND ISSUE_RESOLUTION_STATUS = #{queryVo.issueResolutionStatus}


    AND CORRECTION_COMPLETION_TIME >= #{queryVo.correctionCompletionTimeBegin}


    AND CORRECTION_COMPLETION_TIME <= #{queryVo.correctionCompletionTimeEnd}


    AND TEMPLATE_VERSION = #{queryVo.templateVersion}


    AND FORMAT_STANDARDS = #{queryVo.formatStandards}


    AND VERSION_CONTROL = #{queryVo.versionControl}


    AND COMPLIANCE_CHECK_RESULT = #{queryVo.complianceCheckResult}


    AND CREATE_TIME >= #{queryVo.createTimeBegin}


    AND CREATE_TIME <= #{queryVo.createTimeEnd}


    AND UPDATE_TIME >= #{queryVo.updateTimeBegin}


    AND UPDATE_TIME <= #{queryVo.updateTimeEnd}


    AND CREATE_BY LIKE CONCAT('%', #{queryVo.createBy}, '%')


    AND UPDATE_BY LIKE CONCAT('%', #{queryVo.updateBy}, '%')
